# ================================================================ OA 05 clase 1
L(OA5, 1,
  use="Aprenderé qué es la función inversa usando la idea de una máquina que se puede devolver, y a calcular valores con ella. Sirve para encontrar la entrada original a partir de un resultado, como los kilómetros de un viaje a partir del precio.",
  prior=["Sé evaluar una función en un valor.", "Sé resolver ecuaciones lineales sencillas."],
  explain=[
      "Una función es como una máquina: entra un número x y sale f(x). La función inversa, que se escribe f⁻¹, es la máquina que devuelve la entrada original. Si f(3) = 11, entonces f⁻¹(11) = 3. La inversa responde la pregunta: «¿qué número entró para que saliera este resultado?».",
      "Si f(x) = 2x + 3, la máquina multiplica por 2 y luego suma 3. Para devolverla se deshacen los pasos en orden contrario: primero se resta 3 y luego se divide por 2. Así f⁻¹(11) = (11 − 3) ÷ 2 = 4. En una tabla, la inversa se obtiene intercambiando las columnas de entrada y salida.",
      "Una función solo se puede invertir si cada resultado sale de una sola entrada. Si f(2) = 7 y f(5) = 7, no se sabría si devolver 2 o 5. Atención: f⁻¹ no significa 1/f. El −1 de f⁻¹ indica «inversa», no un exponente.",
  ],
  vocab=[("función inversa", "función que devuelve la entrada original, escrita f⁻¹"), ("entrada", "valor de x que se pone en la máquina"), ("salida", "resultado f(x) que entrega la máquina"), ("orden contrario", "deshacer los pasos empezando por el último"), ("tabla de valores", "lista de pares entrada y salida")],
  worked=[
      ("Inversa con una tabla", "Para f(x) = 2x + 3, completa la tabla de x = 1, 2, 3 y úsala para calcular f⁻¹(13).", ["f(1) = 5, f(2) = 7 y f(3) = 9; la tabla de f⁻¹ intercambia las columnas: 5 → 1, 7 → 2, 9 → 3.", "Para 13 no está en la tabla, así que deshago la máquina: 13 − 3 = 10.", "Luego 10 ÷ 2 = 5."], "f⁻¹(13) = 5"),
      ("Máquina de dos pasos", "Una máquina resta 4 y luego multiplica por 3. Describe su inversa y calcula la entrada que dio 15.", ["La inversa deshace en orden contrario: primero divide por 3 y luego suma 4.", "15 ÷ 3 = 5 y 5 + 4 = 9.", "Compruebo: (9 − 4) · 3 = 15."], "La entrada fue 9"),
  ],
  mist=[
      ("Escribir f⁻¹(x) = 1/f(x).", "Se interpreta el −1 como un exponente.", "Para f(x) = 2x, f⁻¹(8) = 4 (porque 2 · 4 = 8), mientras que 1/f(8) = 1/16."),
      ("Deshacer la máquina «×2 y luego +3» dividiendo por 2 y luego restando 3.", "Se deshacen los pasos en el mismo orden en que se hicieron.", "El último paso fue +3, así que se resta 3 primero y después se divide: f⁻¹(11) = (11 − 3) ÷ 2 = 4."),
  ],
  R=[ex("Si f(x) = x + 5, ¿cuánto es f⁻¹(8)?", "3", "Se busca la entrada que da 8: 3 + 5 = 8."),
     ex("Si f(x) = 3x, ¿cuánto es f⁻¹(12)?", "4", "3 · 4 = 12."),
     ex("Una máquina multiplica por 4 y luego resta 1. ¿Cuál es su inversa? A) sumar 1 y luego dividir por 4 B) dividir por 4 y luego sumar 1", "A", "Se deshacen los pasos en orden contrario: primero el −1 y luego el ×4.")],
  C=[ex("Para f(x) = 2x − 1, ¿cuánto es f⁻¹(9)?", "5", "2 · 5 − 1 = 9."),
     ex("Para f(x) = x/2 + 4, ¿cuánto es f⁻¹(10)?", "12", "10 − 4 = 6 y 6 · 2 = 12; comprobación: 12/2 + 4 = 10."),
     ex("Si f(3) = 11, ¿cuánto es f⁻¹(11)?", "3", "La inversa devuelve la entrada que produjo ese resultado.")],
  A=[ex("La fórmula F(C) = 1,8C + 32 convierte grados Celsius en Fahrenheit. ¿Cuántos °C son 68 °F?", "20 °C", "(68 − 32) ÷ 1,8 = 36 ÷ 1,8 = 20."),
     ex("Una tarifa de ejemplo es T(k) = 1.000 + 400k pesos por k kilómetros. Si alguien pagó 3.000 pesos, ¿cuántos kilómetros recorrió?", "5 km", "(3.000 − 1.000) ÷ 400 = 5."),
     ex("Para f(x) = 5x − 2, ¿cuánto es f⁻¹(18)?", "4", "5 · 4 − 2 = 18.")],
  Z=[ex("Beto dice que f⁻¹(8) = 1/f(8). Para f(x) = 2x, calcula f⁻¹(8) de forma correcta y como lo hizo Beto.", "Correcta: 4; Beto: 1/16", "f⁻¹(8) = 4 porque 2 · 4 = 8, mientras que f(8) = 16 y 1/16 es distinto."),
     ex("Si f(2) = 7 y f(5) = 7, ¿puede f tener inversa? A) Sí B) No", "B", "El resultado 7 vendría de dos entradas, y la inversa no sabría cuál devolver.")],
  D=[ex("Si f(x) = (x + 3)/2, ¿cuánto es f⁻¹(5)?", "7", "La inversa multiplica por 2 y resta 3: 5 · 2 − 3 = 7; comprobación: (7 + 3)/2 = 5."),
     ex("Una máquina lineal (que suma una cantidad fija cada vez que la entrada sube 1) da 17 con la entrada 4 y 23 con la entrada 6. ¿Qué entrada da 41?", "12", "Sube 3 por cada unidad de entrada, así que f(x) = 3x + 5; 3x + 5 = 41 da x = 12.")],
  ctx=[ex("Un plan de celular de ejemplo cobra c(g) = 3.000 + 500g pesos, con g los gigas extra. Si una persona pagó 6.500 pesos, ¿cuántos gigas extra usó?", "7", "(6.500 − 3.000) ÷ 500 = 7.")],
  chk=[ex("Si f(x) = x − 7, ¿cuánto es f⁻¹(2)?", "9", "9 − 7 = 2."),
       ex("Una máquina divide por 5 y luego suma 2. ¿Qué entrada produce 12?", "50", "12 − 2 = 10 y 10 · 5 = 50."),
       ex("Verdadero o falso: f⁻¹(x) significa lo mismo que 1/f(x).", "Falso", "El −1 indica función inversa, no un exponente.")],
  op=("Considera la máquina f(x) = 3x + 2. Haz una tabla con las entradas 0, 1, 2 y 3, escribe la tabla de f⁻¹ intercambiando columnas, describe con palabras los pasos de la máquina inversa y calcula f⁻¹(14). Comprueba el resultado.",
      "f: 2, 5, 8, 11. f⁻¹: 2 → 0, 5 → 1, 8 → 2, 11 → 3. La inversa resta 2 y luego divide por 3. f⁻¹(14) = (14 − 2) ÷ 3 = 4; comprobación: 3 · 4 + 2 = 14.",
      ["tabla de f correcta", "tabla de f⁻¹ con columnas intercambiadas", "describe la inversa en orden contrario y comprueba"],
      ["dos tablas", "frase con los pasos inversos", "comprobación"],
      ["confundir f⁻¹ con 1/f", "no invertir el orden de los pasos"],
      "Pide que reemplace la respuesta en f para ver si se obtiene 14."),
  reinforce="Para f(x) = 4x + 1, calcula f⁻¹(9), f⁻¹(21) y f⁻¹(−3).",
  extend="Piensa en una máquina que eleva al cuadrado y explica por qué no se puede devolver con certeza cuando sale 9.",
)

# ================================================================ OA 05 clase 2
L(OA5, 2,
  use="Aprenderé a hallar la fórmula de la inversa de una función lineal despejando x. Sirve para convertir unidades y hallar la cantidad a partir del costo.",
  prior=["Sé qué es la función inversa como máquina.", "Sé despejar x en ecuaciones lineales."],
  explain=[
      "Para hallar la inversa de una función lineal f(x) = mx + n (con m distinto de 0) sigue tres pasos: escribe y = mx + n, despeja x en función de y, y finalmente nombra la variable x. Resulta f⁻¹(x) = (x − n)/m. Por ejemplo, para f(x) = 4x + 1: y = 4x + 1, luego x = (y − 1)/4, y f⁻¹(x) = (x − 1)/4.",
      "Para comprobar, se usa la composición: f(f⁻¹(x)) = x y f⁻¹(f(x)) = x. En el ejemplo, f(f⁻¹(x)) = 4 · (x − 1)/4 + 1 = x. También se puede comprobar con un valor: f(2) = 9 y f⁻¹(9) = (9 − 1)/4 = 2.",
      "Si m = 0, la función es constante, como f(x) = 5, y no tiene inversa porque todas las entradas dan el mismo resultado. Hay funciones que son su propia inversa, como f(x) = −x + 7. Cuando m es negativa la fórmula sigue valiendo, pero cuidado con los signos al despejar.",
  ],
  vocab=[("despejar", "dejar x sola en un lado de la igualdad"), ("composición", "aplicar una función al resultado de otra, f(g(x))"), ("función constante", "función que da siempre el mismo resultado"), ("pendiente", "número m en y = mx + n"), ("ordenada al origen", "número n en y = mx + n")],
  worked=[
      ("Inversa de una lineal", "Halla la inversa de f(x) = 6x + 5.", ["Escribo y = 6x + 5.", "Despejo: y − 5 = 6x, entonces x = (y − 5)/6.", "Nombro la variable x: f⁻¹(x) = (x − 5)/6."], "f⁻¹(x) = (x − 5)/6"),
      ("Pendiente negativa", "Halla la inversa de f(x) = −2x + 6 y comprueba con un valor.", ["y = −2x + 6 da 2x = 6 − y, entonces x = (6 − y)/2.", "Así f⁻¹(x) = (6 − x)/2.", "Compruebo: f(1) = 4 y f⁻¹(4) = (6 − 4)/2 = 1."], "f⁻¹(x) = (6 − x)/2"),
  ],
  mist=[
      ("Decir que la inversa de f(x) = 2x + 3 es −2x − 3 (el opuesto).", "Se confunde la inversa con el opuesto de la función.", "Compara: f(1) = 5, así que f⁻¹(5) debe ser 1, pero −2 · 5 − 3 = −13. La inversa correcta es (x − 3)/2."),
      ("Despejar y = 2x + 3 como x = y − 3/2.", "Falta paréntesis: se divide solo el 3 y no todo el numerador.", "x = (y − 3)/2, con el paréntesis."),
  ],
  R=[ex("Despeja x en y = x + 9.", "x = y − 9", "Se resta 9 a ambos lados."),
     ex("¿Cuál es la inversa de f(x) = 5x?", "f⁻¹(x) = x/5", "Se divide por 5 para deshacer la multiplicación."),
     ex("Despeja x en y = 2x + 6.", "x = (y − 6)/2", "Primero se resta 6 y luego se divide por 2.")],
  C=[ex("Halla la inversa de f(x) = 5x − 10.", "f⁻¹(x) = (x + 10)/5", "y + 10 = 5x, entonces x = (y + 10)/5."),
     ex("Halla la inversa de f(x) = x/3 + 2.", "f⁻¹(x) = 3x − 6", "y − 2 = x/3, entonces x = 3(y − 2) = 3y − 6."),
     ex("Halla la inversa de f(x) = −x + 7.", "f⁻¹(x) = 7 − x", "y = −x + 7 da x = 7 − y.")],
  A=[ex("Halla la inversa de f(x) = 0,5x + 3.", "f⁻¹(x) = 2x − 6", "y − 3 = 0,5x, entonces x = 2(y − 3) = 2y − 6."),
     ex("La fórmula F(C) = 1,8C + 32 convierte °C en °F. Escribe C en función de F.", "C(F) = (F − 32)/1,8", "Se resta 32 y se divide por 1,8."),
     ex("El precio con IVA (19 %) es P = 1,19N, con N el precio neto. Si P = 11.900 pesos, ¿cuánto vale N?", "10.000 pesos", "N = P ÷ 1,19 = 11.900 ÷ 1,19 = 10.000.")],
  Z=[ex("¿Cuál es la inversa de g(x) = 2x − 4? A) (x − 4)/2 B) (x + 4)/2", "B", "Como g(0) = −4, la inversa debe dar g⁻¹(−4) = 0, y (−4 + 4)/2 = 0."),
     ex("¿Por qué f(x) = 5 (es decir, f(x) = 0x + 5) no tiene inversa?", "Porque da 5 para cualquier entrada", "Todas las entradas llevan al mismo resultado y no se sabe cuál devolver.")],
  D=[ex("f(x) = ax + 3 cumple f⁻¹(11) = 2. ¿Cuánto vale a?", "4", "f(2) = 11, entonces 2a + 3 = 11 y a = 4."),
     ex("Halla la inversa de f(x) = (2x + 1)/3.", "f⁻¹(x) = (3x − 1)/2", "3y = 2x + 1, entonces x = (3y − 1)/2.")],
  ctx=[ex("La ganancia de ejemplo de un taller es G(u) = 150u − 3.000 pesos por vender u unidades. Escribe u en función de G y calcula las unidades si G = 6.000.", "u = (G + 3.000)/150; 60 unidades", "(6.000 + 3.000) ÷ 150 = 9.000 ÷ 150 = 60.")],
  chk=[ex("Halla la inversa de f(x) = x − 7.", "f⁻¹(x) = x + 7", "Se suma 7 para deshacer la resta."),
       ex("Halla la inversa de f(x) = 3x + 9.", "f⁻¹(x) = (x − 9)/3", "y − 9 = 3x."),
       ex("Verdadero o falso: f(f⁻¹(x)) = x.", "Verdadero", "Aplicar la función a su inversa devuelve el número original.")],
  op=("Halla la inversa de f(x) = 4x − 12 y de g(x) = −3x + 9. Comprueba cada una calculando f(f⁻¹(5)) y g(g⁻¹(5)), y explica con una frase por qué cada una tiene inversa.",
      "f⁻¹(x) = (x + 12)/4; f(f⁻¹(5)) = f(17/4) = 17 − 12 = 5. g⁻¹(x) = (9 − x)/3; g(g⁻¹(5)) = g(4/3) = −4 + 9 = 5. Ambas tienen pendiente distinta de 0.",
      ["despeja x con signos correctos", "escribe la inversa con la variable x", "comprueba con composición"],
      ["dos inversas", "dos comprobaciones"],
      ["olvidar el paréntesis al dividir", "confundir inversa con opuesta"],
      "Si la composición no da 5, pide revisar el signo en el paso en que pasó un término al otro lado."),
  reinforce="Halla la inversa de f(x) = x + 12, f(x) = 6x y f(x) = 2x − 8.",
  extend="Explica por qué f(x) = −x + 7 es su propia inversa y busca otra función lineal que también lo sea.",
)

