  ctx=[ex("En la conversión de temperatura, los puntos (0, 32) y (100, 212) están en el gráfico de F(C), de °C a °F. ¿Qué dos puntos están en el gráfico de la conversión inversa?", "(32, 0) y (212, 100)", "Se intercambian las coordenadas de cada punto.")],
